create table agent_sessions(id uuid primary key,owner_id varchar(255) not null,repository_url varchar(1000) not null,branch_name varchar(255),task varchar(10000) not null,state varchar(32) not null,plan varchar(20000),final_diff text,summary varchar(20000),stop_reason varchar(255),cleanup_succeeded boolean not null default false,llm_calls integer not null default 0,input_tokens bigint not null default 0,output_tokens bigint not null default 0,created_at timestamptz not null,updated_at timestamptz not null,version bigint not null default 0);
create table agent_steps(id bigserial primary key,session_id uuid not null references agent_sessions(id),sequence_no integer not null,type varchar(255) not null,status varchar(32) not null,input_json varchar(20000),output_text text,duration_ms bigint not null,created_at timestamptz not null,unique(session_id,sequence_no));
create index idx_steps_session on agent_steps(session_id,sequence_no);
